import type { ComputedRef, InjectionKey } from 'vue'
import { inject } from 'vue'

export interface FieldContext {
  /** Id of the control. The label points at it with `for`. */
  id: string
  /** Id of the label element. */
  labelId: string
  /** Id of the description element. */
  descriptionId: string
  /** Id of the error element. */
  errorId: string
  /** The field is invalid: it was marked `invalid` or it shows an error. */
  invalid: ComputedRef<boolean>
  /** The control is required. */
  required: ComputedRef<boolean>
  /** The control is disabled. */
  disabled: ComputedRef<boolean>
  /** A description is rendered, so the control should reference it. */
  hasDescription: ComputedRef<boolean>
  /** An error is rendered, so the control should reference it. */
  hasError: ComputedRef<boolean>
  /** Called by `ElfFieldDescription` and `ElfFieldError` while they are mounted; returns the cleanup. */
  register: (part: 'description' | 'error') => () => void
}

export const fieldContextKey: InjectionKey<FieldContext> = Symbol('elf-field')

/** The surrounding `ElfField`, or `undefined` when used on its own. Use it to wire a custom control. */
export function useFieldContext(): FieldContext | undefined {
  return inject(fieldContextKey, undefined)
}

import type { VariantProps } from 'class-variance-authority'
import type { HTMLAttributes } from 'vue'
import { cva } from 'class-variance-authority'

export { fieldContextKey, useFieldContext } from './context'
export type { FieldContext } from './context'
export { default as Field } from './Field.vue'
export { default as FieldControl } from './FieldControl.vue'
export { default as FieldDescription } from './FieldDescription.vue'
export { default as FieldError } from './FieldError.vue'
export { default as FieldLabel } from './FieldLabel.vue'

export const fieldVariants = cva(
  'group flex w-full flex-col gap-2',
  {
    variants: {
      orientation: {
        vertical: 'flex-col',
        horizontal: 'sm:flex-row sm:items-start sm:gap-4',
      },
    },
    defaultVariants: {
      orientation: 'vertical',
    },
  },
)

export type FieldVariants = VariantProps<typeof fieldVariants>

export interface FieldProps {
  /** Id of the control. Defaults to a generated, SSR-safe id; the label, description and error ids derive from it. */
  id?: string
  /** Label text. For richer content use the `label` slot or `ElfFieldLabel`. */
  label?: string
  /** Helper text under the control, referenced by the control through `aria-describedby`. */
  description?: string
  /** Error message. When set, the field is invalid: the control gets `aria-invalid="true"` and references the message. */
  error?: string
  /** Marks the field as invalid without a message, for example while a server check runs. */
  invalid?: boolean
  /** The control is required: adds a visual marker to the label and `aria-required="true"` to the control. */
  required?: boolean
  /** The control is disabled: dims the label and sets `disabled` on the control. */
  disabled?: boolean
  /** Place the label above (`vertical`) or beside (`horizontal`, from the `sm` breakpoint) the control. */
  orientation?: FieldVariants['orientation']
  /** Extra classes, merged with the base classes through `cn()`. */
  class?: HTMLAttributes['class']
}

export interface FieldLabelProps {
  /** Extra classes, merged with the base classes through `cn()`. */
  class?: HTMLAttributes['class']
}

export interface FieldDescriptionProps {
  /** Extra classes, merged with the base classes through `cn()`. */
  class?: HTMLAttributes['class']
}

export interface FieldErrorProps {
  /** Extra classes, merged with the base classes through `cn()`. */
  class?: HTMLAttributes['class']
}
